EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) select COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'detected') THEN 1 ELSE 0 END), 0) AS detected, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'overlay_shown') THEN 1 ELSE 0 END), 0) AS overlay_shown, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'share_tapped') THEN 1 ELSE 0 END), 0) AS share_tapped, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'share_completed') THEN 1 ELSE 0 END), 0) AS share_completed, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'private_save_tapped') THEN 1 ELSE 0 END), 0) AS private_save_tapped, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'private_save_completed') THEN 1 ELSE 0 END), 0) AS private_save_completed, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'share_cancelled') THEN 1 ELSE 0 END), 0) AS share_cancelled, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'private_save_cancelled') THEN 1 ELSE 0 END), 0) AS private_save_cancelled, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'share_failed') THEN 1 ELSE 0 END), 0) AS share_failed, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'private_save_failed') THEN 1 ELSE 0 END), 0) AS private_save_failed, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'overlay_replaced') THEN 1 ELSE 0 END), 0) AS overlay_replaced, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'overlay_unavailable') THEN 1 ELSE 0 END), 0) AS overlay_unavailable, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'overlay_interrupted') THEN 1 ELSE 0 END), 0) AS overlay_interrupted, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'overlay_shown') AND (EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'ignored_timeout') OR EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'ignored_dismissed')) AND NOT EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'share_tapped') AND NOT EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'private_save_tapped') THEN 1 ELSE 0 END), 0) AS ignored, COALESCE(SUM(CASE WHEN (EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'share_tapped') AND ((SELECT MAX(COALESCE(s.last_occurred_at, s.occurred_at)) FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage IN ('share_completed', 'share_cancelled', 'share_failed')) IS NULL OR (SELECT MAX(COALESCE(s.last_occurred_at, s.occurred_at)) FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage IN ('share_tapped', 'share_started')) > (SELECT MAX(COALESCE(s.last_occurred_at, s.occurred_at)) FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage IN ('share_completed', 'share_cancelled', 'share_failed'))) OR EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'private_save_tapped') AND ((SELECT MAX(COALESCE(s.last_occurred_at, s.occurred_at)) FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage IN ('private_save_completed', 'private_save_cancelled', 'private_save_failed')) IS NULL OR (SELECT MAX(COALESCE(s.last_occurred_at, s.occurred_at)) FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage IN ('private_save_tapped', 'private_save_started')) > (SELECT MAX(COALESCE(s.last_occurred_at, s.occurred_at)) FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage IN ('private_save_completed', 'private_save_cancelled', 'private_save_failed')))) THEN 1 ELSE 0 END), 0) AS unfinished, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'share_tapped') AND EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'share_completed') THEN 1 ELSE 0 END), 0) AS share_converted, COALESCE(SUM(CASE WHEN EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'private_save_tapped') AND EXISTS (SELECT 1 FROM screenshot_capture_stages s WHERE s.capture_id = c.id AND s.stage = 'private_save_completed') THEN 1 ELSE 0 END), 0) AS private_save_converted from "screenshot_captures" as "c";
